import React, { Fragment, useState, useEffect } from "react";
import { Col, Form, FormGroup, Input, Label, Row } from "reactstrap";
import { Btn, H4, P } from "../AbstractElements";
import { ForgotPassword, Password, RememberPassword, LoginTitle, LoginsubTitle, EmailPhone } from "../Constant";
import { toast } from "react-toastify";
import man from "../assets/images/dashboard/1.png";
import SocialAuth from "./Tabs/LoginTab/SocialAuth";
import { Outlet, Link } from "react-router-dom";

import rehabImg from '../assets/images/GKS/gks-logo1.webp';

const Login = ({ selected }) => {
  const [identifier, setIdentifier] = useState(""); // ✅ Updated state name
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [togglePassword, setTogglePassword] = useState(false);

  const [value, setValue] = useState(localStorage.getItem("profileURL") || man);
  const [name, setName] = useState(localStorage.getItem("Name") || "");

  //remember me
  const [rememberMe, setRememberMe] = useState(false);
  useEffect(() => {
    const remembered = localStorage.getItem("rememberMe") === "true";
    const savedIdentifier = remembered ? localStorage.getItem("rememberedIdentifier") : "";

    setRememberMe(remembered);
    setIdentifier(savedIdentifier);
  }, []);

  useEffect(() => {
    localStorage.setItem("profileURL", value);
    localStorage.setItem("Name", name);
  }, [value, name]);

  const loginAuth = async (e) => {
    e.preventDefault();
    setLoading(true);
  
    try {
      const trimmedIdentifier = (identifier || "").trim();
      const response = await fetch("https://gks-yjdc.onrender.com/api/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          identifier: trimmedIdentifier,
          password: password,
        }),
      });
  
      const data = await response.json();
  
      if (response.ok && data.success) {
        // ✅ Extract token and user from nested data
        const token = data.data.token;
        const user = data.data.user;

        // ✅ Store branches in localStorage
        localStorage.setItem("Branch_Detail", JSON.stringify(user.Branch_Detail));
  
        // ✅ Store login data in localStorage
        localStorage.setItem("login", "true");
        localStorage.setItem("Authorization", token);
        localStorage.setItem("user_id", user.user_id);
        localStorage.setItem("profileURL", man);
        localStorage.setItem("Name", user.name);
        const resolvedRoleType = user.isRoleType || (Number(user.isRole) === 5 ? "LabOperator" : Number(user.isRole) === 3 ? "BranchOperator" : Number(user.isRole) === 2 ? "BranchAdmin" : "SuperAdmin");
        localStorage.setItem("isRoleType", resolvedRoleType);
        localStorage.setItem("isRole", String(user.isRole || (resolvedRoleType === "LabOperator" ? 5 : 1)));
  
        // ✅ Handle Remember Me
        if (rememberMe) {
          localStorage.setItem("rememberMe", "true");
          localStorage.setItem("rememberedIdentifier", identifier);
        } else {
          localStorage.removeItem("rememberMe");
          localStorage.removeItem("rememberedIdentifier");
        }
  
        toast.success("Login successful!");
  
        // ✅ Redirect to dashboard or Lab requests for Lab Operator
        setTimeout(() => {
          if (resolvedRoleType === "LabOperator" || Number(user.isRole) === 5) {
            window.location.href = `${process.env.PUBLIC_URL}/BA/Blood-Analysis`;
          } else {
            window.location.href = `${process.env.PUBLIC_URL}/dashboard/Home`;
          }
        }, 800);
      } else {
        // ✅ Check if credentials match any created Branch Admin
        const localAdmins = JSON.parse(localStorage.getItem("gks_branch_admins") || "[]");
        const cleanIdent = (identifier || "").trim().toLowerCase();
        const matchedAdmin = localAdmins.find(
          (a) =>
            (a.username?.toLowerCase() === cleanIdent ||
              a.email?.toLowerCase() === cleanIdent ||
              a.phone?.trim() === (identifier || "").trim()) &&
            (a.password === password || (!a.password && password === "Gks@12345"))
        );

        if (matchedAdmin) {
          if (!matchedAdmin.isActive) {
            toast.error("This Branch Admin account is deactivated!");
            setLoading(false);
            return;
          }

          localStorage.setItem(
            "Branch_Detail",
            JSON.stringify([
              {
                Branch_id: matchedAdmin.branch_id,
                Branch_name: matchedAdmin.branch_name,
              },
            ])
          );
          localStorage.setItem("Selected_Branch_ID", matchedAdmin.branch_id);
          localStorage.setItem("login", "true");
          localStorage.setItem("Authorization", `mock-admin-token-${matchedAdmin.id}`);
          localStorage.setItem("user_id", matchedAdmin.id);
          localStorage.setItem("profileURL", man);
          localStorage.setItem("Name", matchedAdmin.name);
          localStorage.setItem("isRoleType", "BranchAdmin");
          localStorage.setItem("branch_admin_user", JSON.stringify(matchedAdmin));

          if (rememberMe) {
            localStorage.setItem("rememberMe", "true");
            localStorage.setItem("rememberedIdentifier", identifier);
          } else {
            localStorage.removeItem("rememberMe");
            localStorage.removeItem("rememberedIdentifier");
          }

          toast.success(`Login successful! Welcome, ${matchedAdmin.name}`);
          setTimeout(() => {
            window.location.href = `${process.env.PUBLIC_URL}/dashboard/Home`;
          }, 800);
          return;
        }

        // ✅ Handle invalid login attempts
        console.warn("Login response from backend:", data);
        const serverError = data.error || data.message || "";
        const message = serverError.toLowerCase();

        if (message.includes("patient") && message.includes("gks id")) {
          toast.error(serverError || "Patients must login with their GKS ID (e.g. GKS_...)");
        } else if (message.includes("password")) {
          toast.error("Invalid Password!");
        } else if (
          message.includes("identifier") ||
          message.includes("email") ||
          message.includes("phone")
        ) {
          toast.error("Invalid Email or Phone!");
        } else {
          toast.error(serverError || "Invalid credentials!");
        }
      }
    } catch (error) {
      console.error("Login error:", error);

      // ✅ Check local Branch Admins on network failure as well
      const localAdmins = JSON.parse(localStorage.getItem("gks_branch_admins") || "[]");
      const cleanIdent = (identifier || "").trim().toLowerCase();
      const matchedAdmin = localAdmins.find(
        (a) =>
          (a.username?.toLowerCase() === cleanIdent ||
            a.email?.toLowerCase() === cleanIdent ||
            a.phone?.trim() === (identifier || "").trim()) &&
            (a.password === password || (!a.password && password === "Gks@12345"))
      );

      if (matchedAdmin) {
        if (!matchedAdmin.isActive) {
          toast.error("This Branch Admin account is deactivated!");
          setLoading(false);
          return;
        }

        localStorage.setItem(
          "Branch_Detail",
          JSON.stringify([
            {
              Branch_id: matchedAdmin.branch_id,
              Branch_name: matchedAdmin.branch_name,
            },
          ])
        );
        localStorage.setItem("Selected_Branch_ID", matchedAdmin.branch_id);
        localStorage.setItem("login", "true");
        localStorage.setItem("Authorization", `mock-admin-token-${matchedAdmin.id}`);
        localStorage.setItem("user_id", matchedAdmin.id);
        localStorage.setItem("profileURL", man);
        localStorage.setItem("Name", matchedAdmin.name);
        localStorage.setItem("isRoleType", "BranchAdmin");
        localStorage.setItem("branch_admin_user", JSON.stringify(matchedAdmin));

        if (rememberMe) {
          localStorage.setItem("rememberMe", "true");
          localStorage.setItem("rememberedIdentifier", identifier);
        } else {
          localStorage.removeItem("rememberMe");
          localStorage.removeItem("rememberedIdentifier");
        }

        toast.success(`Login successful! Welcome, ${matchedAdmin.name}`);
        setTimeout(() => {
          window.location.href = `${process.env.PUBLIC_URL}/dashboard/Home`;
        }, 800);
        return;
      }

      toast.error("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };
  
  

  return (
    <Fragment>
      <div className="p-0 container-fluid">
        <Row>
          <Col className="col-12">
            <div className="login-card">
              <div className="login-main login-tab">
                <Form className="theme-form" onSubmit={loginAuth}>
                  <img src={rehabImg} alt="rehab logo" className="d-flex" />
                  <H4>{LoginTitle}</H4>
                  <P>{LoginsubTitle}</P>
                  <FormGroup>
                    <Label className="col-form-label">{EmailPhone}</Label>
                    <Input
                      className="form-control"
                      type="text"
                      required
                      autoComplete="current-email"
                      value={identifier}
                      onChange={(e) => setIdentifier(e.target.value)}
                    />
                  </FormGroup>
                  <FormGroup className="position-relative">
                    <Label className="col-form-label">{Password}</Label>
                    <Input
                      className="form-control"
                      type={togglePassword ? "text" : "password"}
                      required
                      autoComplete="current-password"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                    />
                    <div className="show-hide" onClick={() => setTogglePassword(!togglePassword)}>
                      <span className={togglePassword ? "" : "show"}></span>
                    </div>
                  </FormGroup>
                  <div className="form-group mb-0">
                    <div className="checkbox ms-3 mb-3">
                      <Input id="checkbox1" type="checkbox" checked={rememberMe}
                        onChange={(e) => setRememberMe(e.target.checked)} />
                      <Label className="text-muted" for="checkbox1">
                        {RememberPassword}
                      </Label>
                    </div>
                    <Link className="link" to={`${process.env.PUBLIC_URL}/pages/authentication/forget-pwd`}>
                      {ForgotPassword}
                    </Link>

                    <Btn attrBtn={{ color: "primary", className: "btn-block w-100", disabled: loading }}>
                      {loading ? "Logging in..." : "Login"}
                    </Btn>
                  </div>
                  <SocialAuth />
                </Form>
              </div>
            </div>
          </Col>
        </Row>
      </div>
    </Fragment>
  );
};

export default Login;
